    let flags: CULong;

    core::arch::asm!(
        "pushfq",
        "pop {flags}",
        flags = lateout(reg) flags,
        options(preserves_flags),
    );

    if flags & 0x200 == 0 {
        1
    } else {
        0
    }
}
